type Command = { id: string; label: string; group: string };

export function mountCommandPalette(dialog: HTMLDialogElement, app: { commands: readonly Command[]; recent: readonly string[]; query(value: string): void; moveActive(delta: number): void; run(id: string): void }) {
  dialog.innerHTML = `<form class="command-palette" method="dialog"><label>Command <input type="search" data-query autocomplete="off" aria-controls="command-results"></label><div id="command-results" role="listbox" aria-label="Command results"></div></form>`;
  const input = dialog.querySelector<HTMLInputElement>('[data-query]')!;
  const results = dialog.querySelector<HTMLElement>('#command-results')!;
  const render = (commands: readonly Command[]) => { results.replaceChildren(); if (!commands.length) { results.textContent = 'No commands found.'; return; } for (const command of commands) { const option = document.createElement('button'); option.type = 'button'; option.role = 'option'; option.textContent = command.label; option.dataset.commandId = command.id; option.onclick = () => app.run(command.id); results.append(option); } };
  input.addEventListener('input', () => app.query(input.value));
  input.addEventListener('keydown', event => { if (event.key === 'ArrowDown') { event.preventDefault(); app.moveActive(1); } if (event.key === 'ArrowUp') { event.preventDefault(); app.moveActive(-1); } });
  render(app.commands);
}
